  // ApplyRawHdrToDbHdr skips empty subjects. A subject containing only a
  // reply prefix has an empty stored value and must replace the old one.
  if (updated.subject.IsEmpty() && (flags & nsMsgMessageFlags::HasRe)) {
    MOZ_TRY(msgHdr->SetSubject(""_ns));
  }

  // Setting `instigator` (the 4th argument to `NotifyHdrChangeAll`) to
  // nullptr should be fine here, the only listener that actually cares about
  // it is the `nsMsgDBView` to check whether it instigated the change itself
  // (which it hasn't in this case).
  MOZ_TRY(mDB->NotifyHdrChangeAll(msgHdr, oldFlags, flags, nullptr));

  if (messageSize) {
    MOZ_TRY(msgHdr->SetMessageSize(messageSize));
  }
  if (!preview.IsEmpty()) {
    MOZ_TRY(msgHdr->SetStringProperty("preview", preview));
  }

  MOZ_TRY(mDB->Commit(nsMsgDBCommitType::kLargeCommit));
  return NS_OK;
};

NS_IMETHOD OnReadStatusChanged(const nsACString& ewsId,
                               bool isRead) override {
  // Get the header for the message with ewsId and update its read flag in the
  // database.
  RefPtr<nsIMsgDBHdr> existingHeader;
  nsresult rv =
      mDB->GetMsgHdrForEwsItemID(ewsId, getter_AddRefs(existingHeader));
  NS_ENSURE_SUCCESS(rv, rv);
  if (!existingHeader) {
    // The message might have been deleted locally before we got around to
    // processing the read status change (as happens when a draft is replaced
    // by a newer revision of itself). Let the consumer decide what to do
    // about it.
    return NS_MSG_MESSAGE_NOT_FOUND;
  }

  return existingHeader->MarkRead(isRead);
};

NS_IMETHOD OnMessageDeleted(const nsACString& ewsId) override {
  RefPtr<nsIMsgDBHdr> existingHeader;
  nsresult rv =
      mDB->GetMsgHdrForEwsItemID(ewsId, getter_AddRefs(existingHeader));
  NS_ENSURE_SUCCESS(rv, rv);

  if (!existingHeader) {
    // If we don't have a header for this message ID, it means we have already
    // deleted it locally. This can happen in legitimate situations, e.g. when
    // syncing the message list after deleting a message from Thunderbird (in
    // which case, the server's sync response will include a `Delete` change
    // for the message we've just deleted).
    return NS_OK;
  }

  // Delete from DB and from the nsIMsgPluggableStore (if present).
  return LocalDeleteMessages(mFolder, {existingHeader});
};

NS_IMETHOD OnSyncStateTokenChanged(
    const nsACString& syncStateToken) override {
  return mFolder->SetStringProperty(kSyncStateProperty, syncStateToken);
};

// Called when the operation succeeds.
NS_IMETHOD OnSyncComplete() override {
  // We might have processed unread count updates via `OnMessageUpdated`, in
  // which case we need to make sure the message counts are up to date.
  MOZ_TRY(mDB->SyncCounts());
  MOZ_TRY(mFolder->UpdateSummaryTotals(true));

  MOZ_ASSERT(mNewMessages.Length() == mNewHeaders.Length());
  mOnStop(NS_OK, mNewMessages, mNewHeaders);
